// 염색체별 유전자 인덱스 (좌표 검색용)
const GENE_BY_CHROMOSOME = {};
FUNRICEGENES_ALL.forEach(gene => {
    if (gene.m && gene.m !== 'None') {
        // LOC_Os01g12345 -> Chr1
        const match = gene.m.match(/LOC_Os(\d+)g/);
        if (match) {
            const chr = 'Chr' + parseInt(match[1]);
            if (!GENE_BY_CHROMOSOME[chr]) GENE_BY_CHROMOSOME[chr] = [];
            GENE_BY_CHROMOSOME[chr].push(gene);
        }
    }
});

